// Minimal CJS shim for @deepseek-ai/schemastery (real package is ESM; GraalJS
// standalone CommonJS require cannot load it). Surface copied from how the
// dsh repeat-tool-reminder plugin uses it: z.object / z.array / z.number /
// z.string with chained .default(). The object schema's parse fills defaults,
// so calling Config.parse(...) behaves like schemastery for this plugin's
// shape. The Java bridge currently passes config straight to apply without
// schemastery validation, so parse is exercised only if the test chooses to.

function baseSchema() {
  const s = { _default: undefined, __schemastery: true }
  s.default = (v) => { s._default = v; return s }
  s.optional = () => s
  s.parse = (v) => (v === undefined && s._default !== undefined ? s._default : v)
  return s
}

const z = {
  object(shape) {
    const s = baseSchema()
    s._shape = shape
    s.strict = () => s
    s.parse = (v) => {
      const input = v == null ? {} : v
      const out = {}
      for (const [k, sub] of Object.entries(shape)) out[k] = sub.parse(input[k])
      return out
    }
    return s
  },
  array(item) { const s = baseSchema(); s._item = item; return s },
  number() { return baseSchema() },
  string() { return baseSchema() },
}

module.exports = z
module.exports.default = z
